  async function heartbeat(){if(!state.online||!state.location.enabled||!state.session||!Number.isFinite(Number(state.location.lat))||!Number.isFinite(Number(state.location.lng)))return;const record={online:true,riderId:state.session.uid,riderName:state.profile.fullName||state.session.email,updatedAt:Date.now(),city:state.profile.city||"",lat:Number(state.location.lat),lng:Number(state.location.lng)},current=primaryActiveJob();if(Number.isFinite(Number(state.location.accuracy)))record.accuracy=Number(state.location.accuracy);record.activeOrderId=current?String(current.id||"").slice(0,80):"";await db("PATCH",ROOT+"/riderPresence/"+state.session.uid,record)}
  function closeRealtime(){(state.watchers||[]).forEach(w=>{try{w.close()}catch(_){}});state.watchers=[]}
  function watch(path){if(typeof EventSource==="undefined"||!state.session||!state.session.idToken)return;try{const es=new EventSource(dbUrl(path,state.session.idToken));const changed=()=>{clearTimeout(state.syncDebounce);state.syncDebounce=setTimeout(()=>syncApproved(true).then(()=>renderAfterLiveSync()).catch(()=>{}),250)};es.addEventListener("put",changed);es.addEventListener("patch",changed);state.watchers.push(es)}catch(_){}}
  function startPoll(){clearInterval(state.timer);closeRealtime();watch(ROOT+"/riderOffers/"+state.session.uid);watch(ROOT+"/riderJobs/"+state.session.uid);watch(ROOT+"/riderPresence/"+state.session.uid);state.timer=setInterval(()=>{if(document.visibilityState==="visible"&&state.network)heartbeat().then(()=>{state.error=""}).catch(e=>{state.error=friendly(e);render({preserve:true})}).then(()=>syncProfile()).then(()=>shouldAutoRefreshRewards(state.route)?loadRiderRewards(false,Date.now()):null).catch(()=>{})},20000);if(state.online&&state.network)heartbeat().catch(e=>{state.error=friendly(e);render({preserve:true})});if(shouldAutoRefreshRewards(state.route))loadRiderRewards(false,Date.now()).catch(()=>{})}
  async function refresh(){if(state.loading)return;state.loading=true;render({preserve:true});try{await syncProfile();await syncApproved(true);toast("Partner workspace refreshed.","success")}catch(_){toast("Refresh failed.","danger")}finally{state.loading=false;render({preserve:true})}}
  function requestLocation(forOnline){state.pendingOnline=!!forOnline;if(window.FeastlyRiderNative&&FeastlyRiderNative.requestLocationAccess)FeastlyRiderNative.requestLocationAccess();else toast("Location permission is available in the installed app.","danger")}
  window.riderLocationPermissionResult=function(granted,enabled,lat,lng,accuracy){const valid=Number.isFinite(Number(lat))&&Number.isFinite(Number(lng)),precise=Number.isFinite(Number(accuracy))&&Number(accuracy)>=0&&Number(accuracy)<=100;state.location={granted:!!granted,enabled:!!enabled,lat:valid?Number(lat):state.location.lat,lng:valid?Number(lng):state.location.lng,accuracy:precise?Number(accuracy):state.location.accuracy};if(state.pendingOnline){if(granted&&enabled&&valid&&precise){state.pendingOnline=false;setOnline(true)}else if(!granted||!enabled){state.pendingOnline=false;state.online=false;toast("Turn on Location before going online.","danger")}else toast("Waiting for an accurate current location…","warning")}else if((!granted||!enabled)&&state.online){setOnline(false,true);toast("You were taken offline because Location is unavailable.","danger")}else if(state.online&&valid&&precise){heartbeat().catch(()=>{});if(!primaryActiveJob())startAvailabilityTracking()}render({preserve:true})};
  window.riderTrackingNativeState=function(status,message){const code=String(status||""),copy=String(message||"");state.trackingNativeState=code||state.trackingNativeState;if(code==="active"){clearTimeout(state.trackingRecoveryTimer);state.trackingError="";render({preserve:true});return}if(code==="sync_error"){const current=primaryActiveJob();if(waitingForRestaurantHandover(current)){quiesceRestaurantWaitTracking(current);render({preserve:true});return}state.trackingError=copy||"Live tracking will retry automatically.";scheduleTrackingRecovery();render({preserve:true});return}if(code==="location_off"){clearTimeout(state.trackingRecoveryTimer);state.location.enabled=false;state.online=false;setPendingOffline(true);persistActiveTracking(null);state.trackingError=copy||"Phone Location was turned off.";render({preserve:true});return}if(code==="auth_required"){const current=primaryActiveJob();if(waitingForRestaurantHandover(current)){quiesceRestaurantWaitTracking(current);render({preserve:true});return}state.trackingError=copy||"Secure tracking session needs to reconnect.";if(state.session){state.session.expiresAt=0;persist();ensure().then(s=>{const native=window.FeastlyRiderNative;if(native&&native.refreshDeliveryTrackingCredentials)native.refreshDeliveryTrackingCredentials(s.idToken,s.refreshToken||"",CONFIG.apiKey||"");const current=primaryActiveJob(),phase=trackingPhaseForJob(current);if(current&&state.online&&!waitingForRestaurantHandover(current)&&trackingStartRequired(current,phase))return startTracking(current,phase)}).catch(()=>{state.trackingError="Secure tracking session expired. Reopen the app and sign in again.";render({preserve:true})})}render({preserve:true});return}if(code==="stopped"){clearTimeout(state.trackingRecoveryTimer);if(!state.trackingOrderId)state.trackingError="";render({preserve:true})}};
  async function setOnline(value,forced){if(!value&&!forced&&activeJobs().length){toast("Finish or hand off the active delivery before going offline.","danger");return}if(value&&(!state.location.granted||!state.location.enabled||!Number.isFinite(Number(state.location.lat))||!Number.isFinite(Number(state.location.lng))||!Number.isFinite(Number(state.location.accuracy))||Number(state.location.accuracy)>100)){requestLocation(true);return}if(!state.network){if(!value){const preserveTracking=shouldPreserveActiveDeliveryTracking();state.online=false;setPendingOffline(true);if(!preserveTracking)stopTracking("offline");toast(preserveTracking?"Internet was lost. Active delivery tracking will retry automatically while new jobs stay paused.":"You are offline on this device. Scraveit will confirm it when internet returns.","danger");render({preserve:true})}else toast("Reconnect before going online.","danger");return}const current=primaryActiveJob(),record={online:!!value,riderId:state.session.uid,riderName:state.profile.fullName||state.session.email,updatedAt:Date.now(),city:state.profile.city||"",activeOrderId:value&&current?String(current.id||"").slice(0,80):""};if(value){record.lat=Number(state.location.lat);record.lng=Number(state.location.lng);record.accuracy=Number(state.location.accuracy)}try{await db("PUT",ROOT+"/riderPresence/"+state.session.uid,record);state.online=!!value;setPendingOffline(false);if(!value)stopTracking("offline");else if(!current)await startAvailabilityTracking();toast(value?"You are online for nearby delivery offers.":"You are offline.",value?"success":"");render({preserve:true});if(value)setTimeout(()=>loadRiderRewards(true,Date.now()),1500)}catch(e){if(!value){state.online=false;setPendingOffline(true);stopTracking("offline")}toast(friendly(e),"danger")}}
  function openNavigation(destination){if(!destination){toast("Navigation destination is missing.","danger");return}if(window.FeastlyRiderNative&&FeastlyRiderNative.openNavigation)FeastlyRiderNative.openNavigation(String(destination));else toast("Navigation is available in the installed app.","danger")}
  async function startAvailabilityTracking(){if(!state.online||primaryActiveJob()||!state.location.granted||!state.location.enabled)return false;try{const s=await ensure(),native=window.FeastlyRiderNative;if(!native||!native.startAvailabilityTracking)throw new Error("NATIVE_AVAILABILITY_UNAVAILABLE");native.startAvailabilityTracking(state.session.uid,state.profile.fullName||"Scraveit Partner",s.idToken,s.refreshToken||"",CONFIG.apiKey||"",state.profile.city||"");state.availabilityTracking=true;state.trackingError="";return true}catch(e){state.availabilityTracking=false;state.trackingError="Background availability could not start. "+friendly(e);render({preserve:true});return false}}
  async function startTracking(o,phase){if(!o||!state.location.granted||!state.location.enabled)return false;const nextPhase=String(phase||trackingPhaseForJob(o)||"pickup");if(trackingSessionHeld(o,nextPhase)&&["starting","active"].includes(String(state.trackingNativeState||""))){state.trackingError="";return true}try{const s=await ensure(),address=o.address||{},lat=Number(address.lat),lng=Number(address.lng),riderName=state.profile.fullName||"Scraveit Partner",native=window.FeastlyRiderNative;if(native&&native.startResilientTracking)native.startResilientTracking(o.userId,o.id,o.restaurantId||"",state.session.uid,riderName,s.idToken,s.refreshToken||"",CONFIG.apiKey||"",Number.isFinite(lat)?lat:0,Number.isFinite(lng)?lng:0,nextPhase,state.profile.city||"",o.status||"");else if(native&&native.startAdvancedTracking)native.startAdvancedTracking(o.userId,o.id,o.restaurantId||"",state.session.uid,riderName,s.idToken,s.refreshToken||"",CONFIG.apiKey||"",Number.isFinite(lat)?lat:0,Number.isFinite(lng)?lng:0,nextPhase);else throw new Error("NATIVE_TRACKING_UNAVAILABLE");state.availabilityTracking=false;state.trackingNativeState="starting";persistActiveTracking(o,nextPhase);state.trackingError="";return true}catch(e){state.trackingNativeState="stopped";state.trackingError="Secure live tracking could not start. "+friendly(e);toast(state.trackingError,"danger");render({preserve:true});return false}}
  function stopTracking(reason){const native=window.FeastlyRiderNative;try{if(native&&native.stopDeliveryTrackingWithReason)native.stopDeliveryTrackingWithReason(reason||"stopped");else if(native&&native.stopDeliveryTracking)native.stopDeliveryTracking()}catch(_){}state.availabilityTracking=false;state.trackingNativeState="stopped";persistActiveTracking(null);state.trackingError=""}
  function scheduleTrackingRecovery(){clearTimeout(state.trackingRecoveryTimer);state.trackingRecoveryTimer=setTimeout(async()=>{const current=primaryActiveJob(),native=window.FeastlyRiderNative;if(waitingForRestaurantHandover(current)){quiesceRestaurantWaitTracking(current);render({preserve:true});return}if(!state.session||!state.network||!state.online||!current||!native)return;try{const s=await ensure();if(typeof native.refreshDeliveryTrackingCredentials==="function")native.refreshDeliveryTrackingCredentials(s.idToken,s.refreshToken||"",CONFIG.apiKey||"");await startTracking(current,trackingPhaseForJob(current));await syncApproved(true).catch(()=>{})}catch(_){}},1500)}
  function arrivalVerificationPendingMessage(message){return/already in progress|being checked/i.test(String(message||""))}
  function hasVerifiedRestaurantArrival(orderId){const pointer=state.jobPointers[orderId]||{},current=job(orderId);return pointer.phase==="at_restaurant"||Number(pointer.arrivedRestaurantAt||0)>0||!!(pointer.arrivalVerification&&pointer.arrivalVerification.verified)||!!(current&&["Handed to rider","Out for delivery","Near you","Arrived","Delivered"].includes(current.status))}
  async function settleRestaurantArrival(orderId){for(const waitMs of [1200,1800]){await new Promise(resolve=>setTimeout(resolve,waitMs));await syncApproved(true).catch(()=>{});if(hasVerifiedRestaurantArrival(orderId))return true}return hasVerifiedRestaurantArrival(orderId)}
  async function claimOffer(id){const offer=availableOffers().find(o=>o.id===id);if(state.pendingOfferAction)return;if(!offer||!state.online){closeSheet();toast(state.online?"This offer has expired or was assigned.":"Go online before accepting an offer.","danger");return}if(!canReserveNextDelivery()){toast("Finish the current delivery before accepting another.","danger");return}if(!state.location.enabled){requestLocation(true);return}const finishingCurrent=activeJobs().length===1;state.pendingOfferAction=id;pauseNativeOffer(offer);renderSheet();try{await cloudClaim(id)}catch(e){const stillAvailable=await recoverOfferAfterFailure(offer,e),message=friendly(e);toast(!stillAvailable&&terminalOfferFailure(message)?"This offer expired or was assigned to another rider.":"Could not accept this offer. "+message,"danger");state.pendingOfferAction="";render({preserve:true});return}permanentlySilenceNativeOffer(offer);delete state.queue[id];try{await syncApproved(true);const current=job(id);if(current){state.selectedJobId=id;if(!finishingCurrent){await startTracking(current,"pickup");openNavigation(current.restaurantLocation&&current.restaurantLocation.address||offer.restaurantAddress);go("jobDetail",{jobId:id})}}closeSheet();toast(finishingCurrent?"Next delivery secured. Complete the doorstep delivery first.":"Delivery secured. Navigate to the restaurant.","success")}catch(e){closeSheet();toast("Delivery secured. Live details are reconnecting.","warning")}finally{state.pendingOfferAction="";render({preserve:true})}}
  async function declineOffer(id){if(!id||state.pendingOfferAction)return;const offer=availableOffers().find(o=>o.id===id);if(!offer){closeSheet();toast("This offer has already expired.","danger");return}state.pendingOfferAction=id;pauseNativeOffer(offer);renderSheet();try{await cloudDecline(id)}catch(e){await recoverOfferAfterFailure(offer,e);toast("Offer decline failed. "+friendly(e),"danger");state.pendingOfferAction="";render({preserve:true});return}permanentlySilenceNativeOffer(offer);delete state.queue[id];closeSheet();toast("Offer declined. Finding the next nearby rider.","success");try{await syncApproved(true)}catch(_){toast("Offer declined. Delivery offers are reconnecting.","warning")}finally{state.pendingOfferAction="";render({preserve:true})}}
  async function markAtRestaurant(o){if(!o||state.pendingJobAction)return;state.pendingJobAction=o.id;render({preserve:true});try{const result=await cloudMarkAtRestaurant(o.id);state.jobPointers[o.id]=Object.assign({},state.jobPointers[o.id],{phase:"at_restaurant",arrivedRestaurantAt:Number(result&&result.arrivedAt||Date.now()),arrivalVerification:{verified:true}});render({preserve:true});toast(result&&result.idempotent?"Restaurant arrival already verified.":"Arrival at restaurant verified.","success");await syncApproved(true)}catch(e){const message=friendly(e);if(arrivalVerificationPendingMessage(message)){toast("Checking restaurant arrival…","warning");if(await settleRestaurantArrival(o.id)){toast("Arrival at restaurant verified.","success");return}toast(state.trackingError?"Live location is reconnecting. Keep the app open and retry in a few seconds.":"Arrival check is still running. Keep the app open and retry in a few seconds.","warning");return}if(message==="Restaurant arrival could not be verified."&&state.trackingError){await syncApproved(true).catch(()=>{});toast("Live location is reconnecting. Once sync is back, try restaurant arrival again.","warning");return}toast(message,"danger")}finally{state.pendingJobAction="";render({preserve:true})}}
  async function updateStatus(o,status){const valid=o.status==="Handed to rider"&&status==="Out for delivery";if(!valid){toast("That delivery step is not available yet.","danger");return false}try{await cloudStatus(o,status,{});o.status=status;o.updatedAt=Date.now();await startTracking(o,"delivery");openNavigation(o.address&&o.address.address);toast("Delivery moved to "+status+".","success");render({preserve:true});return true}catch(e){toast("Status update failed. "+friendly(e),"danger");await syncApproved(true).catch(()=>{});render({preserve:true});return false}}
  async function confirmDeliveryLocation(o){if(!o||!["Out for delivery","Near you"].includes(o.status))return;const started=await startTracking(o,"delivery");if(!started){toast("Live location could not start. Keep Location on and try again.","danger");return}heartbeat().catch(()=>{});toast("Location shared. Arrival will confirm automatically after GPS verification.","success");setTimeout(()=>syncApproved(true).then(()=>render({preserve:true})).catch(()=>{}),1500)}
  async function completeDelivery(o,otp,cashConfirmed){if(o.status!=="Arrived"){toast("Record arrival at the delivery location before completion.","danger");return}if(o.otpRequired!==true&&o.legacyOtpOrderSuffix!==true){toast("Delivery verification is unavailable for this order. Refresh or contact support.","danger");return}if(o.paymentMethod==="cod"&&!cashConfirmed){toast("Confirm cash collection before completing COD delivery.","danger");return}if(!/^\d{4,6}$/.test(String(otp||""))){toast("Enter the delivery OTP shown by the customer.","danger");return}try{await cloudStatus(o,"Delivered",{deliveryOtp:String(otp),cashCollected:!!cashConfirmed});o.status="Delivered";o.deliveredAt=Date.now();state.rewardsWeekPreview=null;state.rewardsDayKey=earningDateKey();state.rewardsReferenceAt=Date.now();state.rewardsLastSync=0;stopTracking("delivered");closeSheet();toast("Delivery completed and recorded.","success");go("earnings",{},true)}catch(e){toast("Delivery completion failed. "+friendly(e),"danger")}}

  function screenLaunch(){return '<main class="screen no-nav"><div class="content launch"><span class="spinner"></span><strong>Restoring your partner workspace…</strong></div></main>';}
  function screenWelcome(){return'<main class="screen no-nav"><div class="content" style="min-height:calc(100vh - 60px);display:grid;grid-template-rows:auto 1fr auto;gap:28px"><div class="cluster">'+logo()+'<div><div class="brand">'+BRAND+'</div><p class="caption">Deliver with confidence</p></div></div><section class="card hero" style="display:grid;align-content:end;min-height:360px"><div class="stack"><span class="status" style="background:rgba(255,255,255,.16);color:white">PARTNER NETWORK</span><h1 class="display">Clear jobs.<br>Safer journeys.</h1><p class="supporting" style="color:rgba(255,255,255,.82)">Apply securely, control your availability and complete every delivery one step at a time.</p></div></section><div class="stack"><button class="button primary full" data-action="go" data-route="signup">Apply as a delivery partner</button><button class="button tonal full" data-action="go" data-route="login">I already have an account</button><p class="caption" style="text-align:center">Location is shared only during an active assigned delivery.</p></div></div></main>'}
  function screenLogin(){return'<main class="screen no-nav"><div class="content" style="max-width:520px"><div class="stack-lg" style="padding-top:min(6vh,44px)"><div class="cluster">'+logo()+'<div><div class="brand">'+BRAND+'</div><p class="caption">Approved partner access</p></div></div><div><p class="eyebrow">Welcome back</p><h1 class="display" style="margin-top:7px">Ready for the next journey?</h1><p class="supporting" style="font-size:15px;margin-top:11px">Sign in to manage availability, active deliveries and earnings.</p></div>'+banner()+'<form id="login-form" class="card form-grid"><div class="field"><label>Email address</label><input class="input" name="email" type="email" inputmode="email" autocomplete="email" required></div><div class="field"><label>Password</label><input class="input" name="password" type="password" autocomplete="current-password" required></div><button class="button primary full" type="submit" '+(state.loading?'disabled':'')+'>'+(state.loading?'<span class="spinner"></span> Signing in…':'Sign in securely')+'</button><button class="text-button" type="button" data-action="reset-password">Forgot password?</button><div class="divider">or</div><button class="button tonal full" type="button" data-action="google-signin" '+(state.loading?'disabled':'')+'>Continue with Google</button></form><p class="supporting" style="text-align:center">New partner? <button class="text-button" data-action="go" data-route="signup">Create an application</button></p></div></div></main>'}
  function screenSignup(){return'<main class="screen no-nav"><div class="content page">'+top("Create partner account","Start your secure delivery-partner application.")+'<form id="signup-form" class="card form-grid"><div class="field"><label>Full name</label><input class="input" name="name" autocomplete="name" required></div><div class="field"><label>Email address</label><input class="input" name="email" type="email" inputmode="email" autocomplete="email" required></div><div class="field"><label>Mobile number</label><input class="input" name="phone" type="tel" inputmode="tel" autocomplete="tel" required></div><div class="field"><label>Create password</label><input class="input" name="password" type="password" minlength="8" autocomplete="new-password" required><p class="caption">Use 8+ characters with letters and numbers.</p></div><div class="field"><label>Confirm password</label><input class="input" name="confirm" type="password" autocomplete="new-password" required></div><label class="notice info"><input type="checkbox" name="consent" required><span>I agree to the partner application terms and privacy notice.</span></label><button class="button primary full" type="submit">Create account and continue</button></form></div></main>'}
  function docCard(key,title,copy){const data=state.documentDraft[key];return'<article class="card document-card"><div class="cluster between"><div><h3 class="card-title">'+h(title)+'</h3><p class="supporting">'+h(copy)+'</p></div><span class="status '+(data?'success':'warning')+'">'+(data?'Ready':'Required')+'</span></div><div class="document-preview" id="preview-'+key+'">'+(data?'<img src="'+h(data)+'" alt="'+h(title)+' preview">':icon("document","large"))+'</div><label class="button tonal full">'+icon("camera")+' '+(data?'Replace image':'Choose and compress image')+'<input class="sr-only document-input" type="file" accept="image/jpeg,image/png,image/webp" data-document="'+key+'"></label></article>'}
  function screenOnboarding(){const d=state.applicationDraft||{},v=(k,f)=>h(draftValue(k,f));return'<main class="screen no-nav"><div class="content page">'+top("Partner application","Your progress is saved on this device while you choose documents.")+'<div class="stepper"><span class="step-dot done"></span><span class="step-dot done"></span><span class="step-dot"></span></div><div class="notice warning">'+icon("shield","small")+'<span>Upload only a masked Aadhaar copy. Hide the first 8 digits. Choosing a document will not clear the details you already entered.</span></div><form id="onboarding-form" class="stack-lg"><section class="card form-grid"><h2 class="section-title">Contact and city</h2><div class="field"><label>Full name</label><input class="input" name="fullName" value="'+v("fullName",state.profile.fullName||"")+'" required></div><div class="field"><label>Mobile number</label><input class="input" name="phone" type="tel" inputmode="tel" value="'+v("phone",state.profile.phone||"")+'" required></div><div class="field"><label>Operating city</label><input class="input" name="city" value="'+v("city",state.profile.city||"")+'" required></div><div class="field"><label>Residential address</label><textarea class="textarea" name="address" required>'+v("address",state.profile.address||"")+'</textarea></div></section><section class="card form-grid"><h2 class="section-title">Vehicle</h2><div class="field"><label>Vehicle type</label><select class="select" name="vehicleType">'+["Motorcycle","Scooter","Electric two-wheeler","Bicycle"].map(x=>'<option '+(draftValue("vehicleType",state.profile.vehicleType||"Motorcycle")===x?'selected':'')+'>'+h(x)+'</option>').join("")+'</select></div><div class="field"><label>Vehicle registration</label><input class="input" name="vehicleNumber" value="'+v("vehicleNumber",state.profile.vehicleNumber||"")+'" placeholder="AP 00 AB 0000" required></div></section><section class="card form-grid"><h2 class="section-title">Identity details</h2><div class="field"><label>Last 4 digits of Aadhaar</label><input class="input" name="aadhaarLast4" inputmode="numeric" maxlength="4" value="'+v("aadhaarLast4",state.profile.aadhaarLast4||"")+'" required></div><div class="field"><label>PAN number</label><input class="input" name="panNumber" maxlength="10" value="'+v("panNumber",state.profile.panNumber||"")+'" required></div></section><section class="card form-grid"><h2 class="section-title">Referral (optional)</h2><div class="field"><label>Referral code or link</label><input class="input" name="referredByCode" value="'+v("referredByCode",state.profile.referredByCode||"")+'" placeholder="6-digit code or referral link"><p class="caption">Use a rider referral code if someone invited you. The inviter earns only after you complete 25 successful orders.</p></div></section>'+docCard("aadhaarFront","Aadhaar — front","Masked copy; first 8 digits hidden")+docCard("aadhaarBack","Aadhaar — back","Address side of the masked copy")+docCard("panCopy","PAN card copy","Clear image for owner verification")+'<label class="notice info"><input type="checkbox" name="verificationConsent" '+(d.verificationConsent?'checked':'')+' required><span>I confirm these documents belong to me, the Aadhaar copy is masked and I consent to verification.</span></label><button class="button primary full" type="submit">Submit for secure review</button></form></div></main>'}
