  function screenJobs(){const current=primaryActiveJob();return'<main class="screen"><div class="content page">'+banner()+'<header class="cluster between"><div class="cluster"><div class="avatar">'+h(initials())+'</div><div><p class="eyebrow">Delivery workspace</p><h1 class="title">Hello, '+h(String(state.profile.fullName||"Partner").split(" ")[0])+'.</h1></div></div><button class="toggle '+(state.online?'on':'')+'" data-action="toggle-online" aria-label="'+(state.online?'Go offline':'Go online')+'"></button></header>'+health()+(current?currentCard(current):'')+homeLoginSessionTrackerCard()+'<section class="card stack"><div class="cluster between"><div><h2 class="section-title">Availability</h2><p class="supporting">'+(state.online?(canReserveNextDelivery()?'You can receive nearby offers when restaurants accept them.':'Complete the active route before taking another offer.'):'Go online when you are ready to deliver.')+'</p></div><span class="status '+(state.online?'success':'warning')+'">'+(state.online?'ONLINE':'OFFLINE')+'</span></div><button class="button '+(state.online?'danger':'success')+' full" data-action="toggle-online">'+(state.online?'Go offline':'Go online for jobs')+'</button></section><section class="stack"><div class="cluster between"><div><h2 class="section-title">Delivery offers</h2><p class="supporting">Sent as soon as a restaurant accepts an order</p></div><button class="icon-button flat" data-action="refresh">'+icon("refresh")+'</button></div>'+jobSearchInput()+'<div id="offer-results">'+offerResultsMarkup()+'</div></section></div>'+nav()+'</main>'}

