  function tile(lat,lng,z){if(!Number.isFinite(lat)||!Number.isFinite(lng))return"";const n=2**(z||15),x=Math.floor((lng+180)/360*n),y=Math.floor((1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n);return"https://tile.openstreetmap.org/"+(z||15)+"/"+x+"/"+y+".png"}
  function workflowAction(o){const pointer=state.jobPointers[o.id]||{},arrivalPending=state.pendingJobAction===o.id;if(o.status==="Assigned"&&pointer.phase!=="at_restaurant")return'<div class="stack"><button class="button primary full task-action" data-action="navigate-restaurant" data-job-id="'+h(o.id)+'">'+icon("navigation")+' Navigate to restaurant</button><button class="button secondary full" data-action="arrived-restaurant" data-job-id="'+h(o.id)+'" '+(arrivalPending?'disabled':'')+'>'+(arrivalPending?'<span class="spinner"></span> Verifying restaurant arrival…':'I have arrived at the restaurant')+'</button></div>';if(o.status==="Assigned")return'<div class="notice info">'+icon("clock","small")+'<span>Wait for restaurant handover confirmation. Keep the order ID ready for staff.</span></div>';if(o.status==="Handed to rider")return'<button class="button primary full task-action" data-action="confirm-pickup" data-job-id="'+h(o.id)+'">'+icon("check")+' Confirm pickup and start delivery</button>';if(["Out for delivery","Near you"].includes(o.status))return'<div class="stack"><button class="button primary full task-action" data-action="navigate-customer" data-job-id="'+h(o.id)+'">'+icon("navigation")+' Navigate to customer</button><button class="button secondary full" data-action="arrived-customer" data-job-id="'+h(o.id)+'">I am at the delivery location</button></div>';if(o.status==="Arrived")return'<button class="button success full task-action" data-action="complete-delivery" data-job-id="'+h(o.id)+'">'+icon("check")+' Verify and complete delivery</button>';return''}
