  function screenSupport(){return'<main class="screen"><div class="content page">'+top("Partner support","Delivery, account and safety help")+'<div class="notice warning">'+icon("warning","small")+'<span>For an immediate safety or medical emergency, contact local emergency services. In-app support is not an emergency service.</span></div><form id="support-form" class="card form-grid"><div class="field"><label>Topic</label><select class="select" name="topic"><option>Active delivery issue</option><option>Restaurant pickup issue</option><option>Customer unreachable</option><option>Earnings or cash collection</option><option>Account and application review</option><option>Safety concern</option></select></div><div class="field"><label>Details</label><textarea class="textarea" name="message" minlength="10" maxlength="800" required></textarea></div><button class="button primary full" type="submit">Submit support request</button></form></div>'+nav()+'</main>'}

