  function offerSheet(s){const o=availableOffers().find(offer=>offer.id===s.offerId);if(!o)return"";const busy=state.pendingOfferAction===o.id;return sheetShell("Delivery offer",o.restaurantName||"Pickup",'<div class="stack-lg" data-offer-sheet-id="'+h(o.id)+'" data-offer-busy="'+(busy?'1':'0')+'"><div class="notice info">'+icon("shield","small")+'<span>The restaurant accepted this order. Reserve it now; collection unlocks when the kitchen marks it ready. Pickup distance is a GPS straight-line estimate; navigation shows the road route.</span></div><div class="job-route"><div class="route-dots"><span></span><i></i><span></span></div><div class="stack"><div><strong>'+h(o.restaurantName||"Restaurant")+'</strong><p class="supporting">'+h(o.restaurantAddress||o.restaurantArea||"")+'</p></div><div><strong>'+h(o.approximateDropZone||"Approximate drop zone")+'</strong><p class="supporting">Exact address after handover</p></div></div></div><div class="job-metrics"><div class="job-metric"><strong>'+money(o.payout||0)+'</strong><span>Est. payout</span></div><div class="job-metric"><strong>'+h(o.itemCount||0)+'</strong><span>Items</span></div><div class="job-metric"><strong>'+h(o.distanceKm||"—")+'</strong><span>Approx. km</span></div></div><div class="offer-actions"><button class="button primary full" data-action="claim-offer" data-offer-id="'+h(o.id||s.offerId)+'" '+(busy?'disabled':'')+'>'+(busy?'<span class="spinner"></span> Securing offer…':'Accept delivery offer')+'</button><button class="button danger full" data-action="decline-offer" data-offer-id="'+h(o.id||s.offerId)+'" '+(busy?'disabled':'')+'>Decline offer</button></div></div>')}
