  function signoutSheet(){return sheetShell("Sign out?","Your partner session will be removed from this device.",'<div class="stack"><button class="button danger full" data-action="signout">Sign out</button><button class="button tonal full" data-action="close-sheet">Stay signed in</button></div>')}
  function renderSheet(){if(!state.sheet){sheetRegion.innerHTML="";return}const s=state.sheet;if(s.type==="complete"){const live=sheetRegion.querySelector('#complete-form');if(live&&live.dataset.jobId===String(s.jobId||""))return}if(s.type==="offer"){const live=sheetRegion.querySelector('[data-offer-sheet-id]'),busy=state.pendingOfferAction===String(s.offerId||"");if(live&&live.dataset.offerSheetId===String(s.offerId||"")&&live.dataset.offerBusy===(busy?'1':'0'))return}let html="";if(s.type==="reset")html=resetSheet();else if(s.type==="offer")html=offerSheet(s);else if(s.type==="complete")html=completeSheet(s);else if(s.type==="signout")html=signoutSheet();sheetRegion.innerHTML=html}

