  async function signOut(){if(activeJobs().length){toast("Complete or hand off the active delivery before signing out.","danger");return}await unregisterNativePush().catch(()=>{});clearTimeout(state.pushRetryTimer);state.pushReady=false;clearInterval(state.timer);stopTracking("offline");setPendingOffline(false);state.session=null;state.profile={};state.jobs=[];state.queue={};state.online=false;state.rewardsDashboard=null;state.rewardsError="";state.rewardsLoading=false;state.rewardsReferenceAt=0;state.rewardsDayKey="";state.rewardsAutoAnchorApplied=false;persist();localStorage.removeItem("savrivo.partner.profile");state.route="login";state.history=[];closeSheet();render();toast("Signed out safely.")}
