  function compress(file){return new Promise((resolve,reject)=>{if(!file||!/^image\/(jpeg|png|webp)$/.test(file.type)){reject(new Error("Choose a JPEG, PNG or WebP image."));return}if(file.size>10*1024*1024){reject(new Error("Image must be smaller than 10 MB."));return}const reader=new FileReader();reader.onload=()=>{const im=new Image();im.onload=()=>{const scale=Math.min(1,1100/Math.max(im.width,im.height)),canvas=document.createElement("canvas");canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext("2d").drawImage(im,0,0,canvas.width,canvas.height);let data=canvas.toDataURL("image/jpeg",.72);if(data.length>450000)data=canvas.toDataURL("image/jpeg",.55);if(data.length>470000)reject(new Error("Compressed image is too large. Choose a clearer, simpler photo."));else resolve(data)};im.onerror=()=>reject(new Error("Image could not be decoded."));im.src=reader.result};reader.onerror=()=>reject(new Error("Image could not be read."));reader.readAsDataURL(file)})}
