  document.addEventListener("submit",event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();if(form.id==="login-form")login(form);else if(form.id==="signup-form")signup(form);else if(form.id==="onboarding-form")submitOnboarding(form);else if(form.id==="reset-form")reset(form);else if(form.id==="support-form")submitSupport(form);else if(form.id==="rider-payout-profile-form")saveRiderPayoutProfile(form);else if(form.id==="chat-form")sendChat(form);else if(form.id==="complete-form"){const o=job(form.dataset.jobId),fd=new FormData(form);if(fd.get("handover")!=="on"){toast("Confirm recipient handover.","danger");return}completeDelivery(o,String(fd.get("otp")||"").trim(),fd.get("cash")==="on")}});

